        Describe.Lean(DescribeId.Create("ez-shufflediagonal-isdiagonalvertex-bounds-6b6138"), DeclarationHandle.Create("D5/S3/HomologicalAlgebra/EilenbergZilber/ShuffleDiagonal.isDiagonalVertex_bounds"), H("isDiagonalVertex_bounds"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/HomologicalAlgebra/li2026bisimplicialeilenbergzilber")), Blocks(Paragraph(Text("Extract the two facts from `isDiagonalVertex`: `0 < r` and `r < p+q`.")), Paragraph(Text("In this notation, lemma isDiagonalVertex_bounds {p q : ℕ} {μ : Shuffle p q} {r : Index (p + (q))} (hr : isDiagonalVertex μ r) : 0 < r.val ∧ r.val < (p) + (q)."))), DescribeRole.Theorem),
